const cfg=window.SITE_CONFIG,models=window.MODELS;
const art=(wood=false)=>`<svg viewBox="0 0 600 370" role="img" aria-label="Условная иллюстрация бытовки"><defs><pattern id="ribs${wood}" width="${wood?16:9}" height="12" patternUnits="userSpaceOnUse"><rect width="16" height="12" fill="${wood?'#b49a73':'#9ba797'}"/><path d="M0 0V12" stroke="${wood?'#987c56':'#7f8c7a'}" stroke-width="2"/></pattern></defs><ellipse cx="310" cy="303" rx="247" ry="35" fill="#c9cebf"/><path d="M75 128L373 71 537 129 242 192Z" fill="#c9cdbf"/><path d="M75 128L242 192V312L75 240Z" fill="#6e7e6a"/><path d="M242 192L537 129V254L242 312Z" fill="url(#ribs${wood})"/><path d="M65 120L374 60 548 124 539 139 373 79 76 139Z" fill="#354539"/><path d="M275 199L335 186V277L275 290Z" fill="#3d4b40" stroke="#c7ccbd" stroke-width="5"/><path d="M373 181L474 160V222L373 244Z" fill="#c6d8d6" stroke="#e8e9db" stroke-width="7"/><path d="M423 171V233" stroke="#edf1e6" stroke-width="5"/><path d="M101 165L197 203V249L101 210Z" fill="#a7bdb9" stroke="#c6cebd" stroke-width="6"/><path d="M150 184V230" stroke="#dbe1d2" stroke-width="5"/><path d="M260 311V323M510 261V274M91 245V257" stroke="#485346" stroke-width="15"/></svg>`;
const request=(label='Рассчитать стоимость',context='Общий запрос')=>`<button data-request="${context}">${label} <span aria-hidden="true">↗</span></button>`;
const card=m=>`<a class="card" href="/models/${m.id}.html"><div class="picture">${art(m.material==='Дерево')}</div><div class="body"><span class="tag">${m.material} · иллюстрация</span><h3>${m.name}</h3><p>${m.description}</p><div class="foot"><span>Стоимость по запросу</span><span class="arrow">↗</span></div></div></a>`;
const header=`<div class="top"><div class="wrap"><span>Собственное производство · Чебоксары</span><span>Чувашия и соседние регионы</span></div></div><header><nav class="wrap"><a class="logo" href="/">БЫТОВК<span>Ин.</span></a><a href="/catalog.html">Каталог</a><a href="/custom.html">На заказ</a><a href="/production.html">Производство</a><a href="/delivery.html">Доставка</a><a href="/contacts.html">Контакты</a>${request('Обратный звонок')}</nav></header>`;
const footer=`<footer><div class="wrap"><a class="logo" href="/">БЫТОВК<span>Ин.</span></a><span>Производство бытовок в Чебоксарах</span><a href="/privacy.html">Конфиденциальность</a><a href="/consent.html">Обработка данных</a></div><div class="wrap"><p>Иллюстрации показывают условные конструкции. Комплектация и окончательная стоимость согласовываются индивидуально.</p></div></footer><button class="mobile-cta" data-request="Мобильная заявка">Рассчитать стоимость ↗</button>`;
const modal=`<dialog id="lead"><button class="close" aria-label="Закрыть">×</button><h2>Обсудим вашу задачу</h2><p id="context"></p><form><label>Ваше имя (необязательно)<input name="name" autocomplete="given-name" maxlength="80"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+7 (___) ___-__-__" required maxlength="24"></label><label>Что нужно? (необязательно)<textarea name="message" rows="2" maxlength="1500"></textarea></label><label><input type="checkbox" required name="consent"> Даю <a href="/consent.html" target="_blank">согласие на обработку данных</a> и ознакомлен(а) с <a href="/privacy.html" target="_blank">политикой конфиденциальности</a>.</label><p class="notice">${cfg.leadEndpoint?'Отправьте запрос для индивидуального расчёта.':'Демонстрационная форма. Приём заявок будет доступен после подключения отдела продаж.'}</p><button type="submit">${cfg.leadEndpoint?'Отправить заявку':'Проверить заполнение'}</button><p role="status" id="status"></p></form></dialog>`;
let path=location.pathname;let content='';
if(path==='/'||path.endsWith('/index.html'))content=`<div class="hero"><div><span class="eyebrow">От производителя • под вашу задачу</span><h1>Бытовки, с которых<br>начинается <span style="color:#e56231">дело.</span></h1><p>Для стройки, дачи и бизнеса. Производим с нуля в Чебоксарах, доставляем и устанавливаем в Чувашии и соседних регионах.</p><div class="actions">${request()}<a class="button outline" href="/catalog.html">Выбрать в каталоге →</a></div><div class="price">от 50 000 ₽</div><p class="notice">Ориентир для ассортимента. Точная цена — после расчёта.</p></div><div class="visual"><span class="eyebrow" style="padding:14px">Ваше пространство. Ваши задачи.</span>${art()}<div class="caption"><span>Эскиз конструкции / 01</span><span>Концептуальная иллюстрация</span></div></div></div><div class="strip"><div><b>Собственное производство</b><span>Изготавливаем бытовки с нуля</span></div><div><b>Индивидуальная комплектация</b><span>Размеры, утепление, электрика и отделка</span></div><div><b>Доставка и установка</b><span>В Чувашии и соседних регионах</span></div></div><section><div class="sectionhead"><div><span class="eyebrow">Каталог решений</span><h2>Подберите под свою задачу</h2></div><a href="/catalog.html">Весь каталог ↗</a></div><div class="grid">${models.slice(0,3).map(card).join('')}</div></section><section><div class="dark"><div><span class="eyebrow" style="color:#cbd4c4">Индивидуальное изготовление</span><h2>Нужна своя планировка?<br>Начнём с ваших размеров.</h2><p>Расскажите, как будете использовать бытовку. Обсудим конструкцию, отделку и необходимые коммуникации.</p><a class="button" href="/custom.html">Обсудить проект ↗</a></div><div>${art(true)}</div></div></section><section><h2>От задачи до установки</h2><div class="steps"><article><small>01 / ВЫБОР</small><h3>Определяем назначение</h3><p>Выберите категорию или опишите свою задачу.</p></article><article><small>02 / РАСЧЁТ</small><h3>Согласовываем детали</h3><p>Размеры, комплектацию, стоимость и сроки закрепляем при оформлении заказа.</p></article><article><small>03 / ПРОИЗВОДСТВО</small><h3>Изготавливаем и доставляем</h3><p>Условия доставки и установки согласовываются для вашего участка.</p></article></div></section>`;
else if(path==='/catalog.html')content=`<h1 class="page-title">Каталог бытовок</h1><p>Выберите назначение и материал. Диапазон стоимости ассортимента ориентировочно от 50 000 до 1 000 000 ₽. Цены отдельных моделей уточняются.</p><div class="filters"><input id="search" aria-label="Поиск по каталогу" placeholder="Найти бытовку"><select id="category" aria-label="Назначение"><option value="">Все категории</option>${models.map(m=>`<option>${m.category}</option>`).join('')}</select><select id="material" aria-label="Материал"><option value="">Любой материал</option><option>Металл</option><option>Дерево</option></select><button id="reset" class="outline">Сбросить</button></div><p class="notice">Карточки представляют категории ассортимента. Реальные модели и их параметры добавляются производителем.</p><div class="grid" id="results">${models.map(card).join('')}</div><section>${request('Помочь с выбором')}</section>`;
else if(path.startsWith('/models/')){const m=models.find(m=>path.endsWith(m.id+'.html'));if(m)content=`<div class="hero"><div class="visual">${art(m.material==='Дерево')}<p class="caption">Условная иллюстрация, не фотография продукции</p></div><div><span class="eyebrow">${m.category}</span><h1 class="page-title">${m.name}</h1><p>${m.description}</p><h3>Стоимость по запросу</h3><p>Стартовая цена этой категории уточняется производителем.</p>${request('Рассчитать эту бытовку',m.name)}</div></div><section><h2>Характеристики и комплектация</h2><table><tr><td>Размеры и планировка</td><td>По согласованию</td></tr><tr><td>Материал</td><td>${m.material}</td></tr><tr><td>Утепление</td><td>Варианты по запросу</td></tr><tr><td>Электрика и отделка</td><td>По техническому заданию</td></tr><tr><td>Доставка и установка</td><td>Рассчитываются отдельно</td></tr><tr><td>Срок изготовления</td><td>Уточняется при заказе</td></tr></table><p>Это карточка категории. Точные характеристики модели будут добавлены после подтверждения производителем.</p></section>`;}
else {const pages={custom:['Бытовка по вашим размерам','Для нестандартного участка, особой планировки или специфических задач. Изготавливаем строительные, дачные, модульные и другие конструкции на заказ.','Что обсудим перед расчётом','Назначение помещения, размеры, количество комнат, окна и двери. Утепление, электрика и отделка подбираются индивидуально. Если есть эскиз, сообщите об этом при обращении.'],production:['Собственное производство в Чебоксарах','БЫТОВКИн самостоятельно производит бытовки с нуля в Чувашской Республике.','Конструкция под вашу задачу','Производим металлические и деревянные бытовки, блок-контейнеры, модульные, многоэтажные и бронированные конструкции. Фотографии производства и подробности технологического процесса будут добавлены после предоставления компанией.'],delivery:['Доставка и установка','Работаем в Чувашии и соседних регионах. Доставка и установка доступны как дополнительные услуги.','Что нужно для расчёта доставки','Укажите населённый пункт, условия подъезда и место установки. Способ разгрузки, подготовка площадки, цена и дата доставки согласовываются индивидуально.'],contacts:['Контакты БЫТОВКИн','Производство — Чебоксары, Чувашская Республика.','Связаться с производителем', 'Точный адрес, телефон и часы работы ожидают заполнения компанией.'],privacy:['Политика конфиденциальности — проект','Страница требует заполнения реквизитов оператора и согласования перед запуском приёма заявок.','Сведения для заполнения','Оператор — [наименование, ИНН, адрес]. Контакт по вопросам данных — [email]. Цель — обработка обращений и подготовка предложения. Поля — имя, телефон, текст запроса. Необходимо определить сроки хранения, порядок удаления, получателей данных, используемые сервисы и место хранения. В демонстрационном режиме формы данные на сервер не передают.'],consent:['Согласие на обработку данных — проект','Текст необходимо согласовать и заполнить до запуска приёма заявок.','Обработка обращения','Я даю согласие [полное наименование и адрес оператора] на обработку указанных мной имени, телефона и содержания обращения для обратной связи и подготовки предложения. До запуска необходимо указать перечень операций, срок действия согласия, порядок отзыва и контакт оператора. Согласие отмечается отдельным действием пользователя.']};const key=path.split('/').pop().replace('.html',''),p=pages[key];if(p)content=`<section class="textpage"><span class="eyebrow">БЫТОВКИн / Чебоксары</span><h1 class="page-title">${p[0]}</h1><p>${p[1]}</p><h2>${p[2]}</h2><p>${p[3]}</p>${['privacy','consent'].includes(key)?'':request(key==='contacts'?'Заказать обратный звонок':'Обсудить задачу',p[0])}<div id="contacts"></div></section>`;}
document.body.innerHTML=header+`<main class="wrap">${path==='/'?'':`<div class="crumb"><a href="/">Главная</a> / <a href="/catalog.html">Каталог и информация</a></div>`}${content||'<h1>Страница не найдена</h1><a href="/">На главную</a>'}</main>`+footer+modal;
if(cfg.phone){const a=document.createElement('a');a.href='tel:'+cfg.phone.replace(/[^+\d]/g,'');a.textContent=cfg.phone;document.querySelector('nav').append(a);}
const contactBox=document.querySelector('#contacts');if(contactBox){[cfg.address,cfg.email].filter(Boolean).forEach(value=>{const p=document.createElement('p');p.textContent=value;contactBox.append(p);});}
const dialog=document.querySelector('dialog');let selected='';document.addEventListener('click',e=>{const b=e.target.closest('[data-request]');if(b){selected=b.dataset.request;document.querySelector('#context').textContent=selected;document.querySelector('#status').textContent='';dialog.showModal();if(cfg.analyticsEnabled)(window.dataLayer=window.dataLayer||[]).push({event:'lead_open',category:selected});}});document.querySelector('.close').onclick=()=>dialog.close();
document.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,s=document.querySelector('#status'),phone=f.phone.value.replace(/\D/g,'');if(phone.length<10||phone.length>15){s.textContent='Проверьте номер телефона — от 10 до 15 цифр.';return;}if(!cfg.leadEndpoint){s.textContent='Поля заполнены корректно. Заявка не отправлена — приём обращений ещё не подключён.';return;}const b=f.querySelector('button');b.disabled=true;s.textContent='Отправляем…';try{const response=await fetch(cfg.leadEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.name.value,phone:f.phone.value,message:f.message.value,category:selected,consent:true,consentVersion:'draft-1'})});if(!response.ok)throw Error();s.textContent='Заявка отправлена.';f.reset();if(cfg.analyticsEnabled)(window.dataLayer=window.dataLayer||[]).push({event:'lead_success',category:selected});}catch{s.textContent='Не удалось отправить заявку. Попробуйте ещё раз.';}finally{b.disabled=false;}};
if(document.querySelector('#results')){const filter=()=>{const q=document.querySelector('#search').value.toLowerCase(),category=document.querySelector('#category').value,material=document.querySelector('#material').value;const found=models.filter(m=>(!category||m.category===category)&&(!material||m.material===material)&&m.name.toLowerCase().includes(q));document.querySelector('#results').innerHTML=found.map(card).join('')||'<p class="empty">Ничего не найдено. Измените фильтры или обсудите индивидуальный заказ.</p>';};['search','category','material'].forEach(id=>document.getElementById(id).addEventListener('input',filter));document.querySelector('#reset').onclick=()=>{['search','category','material'].forEach(id=>document.getElementById(id).value='');filter();};}
